class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    if @packer
      @store[key] = { payload: @packer.dump(payload), stale: stale }
    else
      @store[key] = { payload: payload, stale: stale }
    end
    true
  end

  def read(key)
    entry = @store[key]
    return nil unless entry
    if @packer
      @packer.load(entry[:payload])
    else
      entry[:payload]
    end
  end

  def sweep
    @store.delete_if { |key, entry|
      if @packer
        entry[:stale] # stale flag is stored directly, not packed
      else
        entry[:stale]
      end
    }
  end
end
