class Cache
  def initialize(packer: nil)
    @packer = packer
    @storage = {}
  end

  def write(key, payload, stale: false)
    if @packer
      @storage[key] = { payload: @packer.dump(payload), stale: stale }
    else
      @storage[key] = { payload: payload, stale: stale }
    end
  end

  def read(key)
    entry = @storage[key]
    return nil unless entry
    payload = entry[:payload]
    if @packer
      @packer.load(payload)
    else
      payload
    end
  end

  def sweep
    @storage.delete_if do |key, entry|
      if @packer
        # The stale flag is stored directly in the entry, not packed,
        # so we can check it directly
        entry[:stale]
      else
        entry[:stale]
      end
    end
  end
end
