    raise ArgumentError, "min must be less than max" if min >= max
    @min = min
    @max = max
  end

  def match?(number)
    @min <= number && number < @max
  end

  # For use in case/when statements
  def ===(other)
    match?(other)
  end

  # For Enumerable#grep
  def grep(obj)
    obj.grep(self)
  end
end
